"""Exact unselected sidewalk-stop construction and post-tick source packet."""
import argparse
import json
import math
import xml.etree.ElementTree as ET
from pathlib import Path

ASSIGNMENT = "training__C229977__NRS-484B-450-1a__motor_vehicle_driver"
CAMERAS = ("overview", "approach", "sidewalk_boundary", "driver_reference")
HERE = Path(__file__).resolve().parent


def request(frame, case_id):
    if type(frame) is not int or not 0 <= frame < 600:
        raise ValueError("frame outside 600-frame contract")
    if case_id not in (ASSIGNMENT + "__probe_1", ASSIGNMENT + "__probe_2"):
        raise ValueError("unknown exact case")
    sidewalk = case_id.endswith("probe_2")
    return {"target_speed_mps": 0.0 if 160 <= frame < 500 else 4.0,
            "target_lateral_m": -5.0 if sidewalk else -1.75,
            "requested_sidewalk_occupancy": sidewalk}


def capture_row(index, native_frame, elapsed_s, actor):
    if type(index) is not int or not 0 <= index < 600 or type(native_frame) is not int:
        raise ValueError("original frame identity required")
    if not isinstance(elapsed_s, (float, int)) or not math.isfinite(elapsed_s):
        raise ValueError("original Native time required")
    pose = actor.get_transform()
    velocity = actor.get_velocity()
    vertices = actor.bounding_box.get_world_vertices(pose)
    if len(vertices) != 8:
        raise ValueError("original vehicle body required")
    return {"frame": index, "native_frame": native_frame, "time_s": elapsed_s,
            "actor_id": actor.id, "blueprint_id": actor.type_id,
            "actor_pose_source": "native_post_tick", "velocity_source": "native_post_tick",
            "speed_mps": math.sqrt(velocity.x ** 2 + velocity.y ** 2 + velocity.z ** 2),
            "body_vertices_m": [[v.x, v.y, v.z] for v in vertices]}


def check(config):
    if (config.get("law_id"), config.get("cell_id"), config.get("actor")) != (
            "NRS-484B-450-1a", "C229977", "motor_vehicle_driver"):
        raise ValueError("frozen identity differs")
    case = config.get("case_id")
    if case not in (ASSIGNMENT + "__probe_1", ASSIGNMENT + "__probe_2"):
        raise ValueError("case identity differs")
    if config.get("rate_hz") != 20 or config.get("duration_s") != 30:
        raise ValueError("30-second timing differs")
    if [c["name"] for c in config.get("cameras", [])] != list(CAMERAS):
        raise ValueError("four-camera profile differs")
    root = ET.parse(HERE / "road.xodr").getroot()
    road = root.find("road")
    if road is None or road.get("id") != "1" or road.get("length") != "100":
        raise ValueError("authored highway absent")
    lane = root.find(".//lane[@id='-2']")
    if lane is None or lane.get("type") != "sidewalk" or float(lane.find("width").get("a")) != 3:
        raise ValueError("authored sidewalk lane absent")
    intended = -5.0 if case.endswith("probe_2") else -1.75
    if request(200, case)["target_lateral_m"] != intended:
        raise ValueError("controlled sidewalk target differs")
    return {"passed": True, "case_id": case, "frames": 600, "rate_hz": 20,
            "cameras": list(CAMERAS), "sidewalk_lane_id": -2,
            "native_capture_implemented": False, "physical_observation_claimed": False}


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    if not args.check:
        raise SystemExit("Native CARLA orchestration remains unfinished")
    print(json.dumps(check(json.loads((HERE / "config.json").read_text())), sort_keys=True))

"""Source-bound sidewalk footprint and halt-history measurement.

A convex local sidewalk polygon is supplied by an acquired map packet, not inferred
from a semantic label. This module measures geometry and timing only. Whether the
surface is legally a sidewalk and whether any exception applies remain review items.
"""
from __future__ import annotations

import hashlib
import json
from math import isfinite
from pathlib import Path

FRAME_RATE = 20
FRAME_COUNT = 600
EPS = 1e-9


def _poly(raw, label):
    if not isinstance(raw, list) or len(raw) < 3:
        raise ValueError(label + " polygon required")
    try:
        pts = [(float(p[0]), float(p[1])) for p in raw]
    except (IndexError, TypeError, ValueError) as exc:
        raise ValueError(label + " polygon invalid") from exc
    if not all(isfinite(x) and isfinite(y) for x, y in pts):
        raise ValueError(label + " polygon nonfinite")
    area = sum(pts[i][0] * pts[(i + 1) % len(pts)][1] -
               pts[(i + 1) % len(pts)][0] * pts[i][1] for i in range(len(pts))) / 2
    if abs(area) < EPS:
        raise ValueError(label + " polygon degenerate")
    if area < 0:
        pts.reverse()
    for i in range(len(pts)):
        ax, ay = pts[i]; bx, by = pts[(i + 1) % len(pts)]; cx, cy = pts[(i + 2) % len(pts)]
        if (bx - ax) * (cy - by) - (by - ay) * (cx - bx) < -EPS:
            raise ValueError(label + " polygon must be convex")
    return pts


def _area(pts):
    if len(pts) < 3:
        return 0.0
    return abs(sum(pts[i][0] * pts[(i + 1) % len(pts)][1] -
                   pts[(i + 1) % len(pts)][0] * pts[i][1] for i in range(len(pts)))) / 2


def _clip(subject, boundary):
    out = subject
    for i, a in enumerate(boundary):
        b = boundary[(i + 1) % len(boundary)]
        def side(p):
            return (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])
        old = out
        out = []
        if not old:
            break
        for j, q in enumerate(old):
            p = old[j - 1]
            sp, sq = side(p), side(q)
            if sq >= -EPS:
                if sp < -EPS:
                    t = sp / (sp - sq)
                    out.append((p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1])))
                out.append(q)
            elif sp >= -EPS:
                t = sp / (sp - sq)
                out.append((p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1])))
    return out


def measure_frame(vehicle, sidewalk):
    v, s = _poly(vehicle, "vehicle"), _poly(sidewalk, "sidewalk")
    overlap = _area(_clip(v, s))
    vehicle_area = _area(v)
    return {
        "vehicle_footprint_area_m2": vehicle_area,
        "sidewalk_overlap_area_m2": overlap,
        "vehicle_overlap_fraction": overlap / vehicle_area,
        "overlap_positive": overlap > EPS,
        "entire_vehicle_on_sidewalk": abs(overlap - vehicle_area) <= EPS,
    }


def _read_bound(path, expected_sha):
    data = Path(path).read_bytes()
    if hashlib.sha256(data).hexdigest() != expected_sha:
        raise ValueError("source hash mismatch")
    return json.loads(data)


def measure_sources(map_path, map_sha256, trace_path, trace_sha256):
    map_packet = _read_bound(map_path, map_sha256)
    trace = _read_bound(trace_path, trace_sha256)
    required_map = ("map_acquisition", "highway_boundary_source", "property_boundary_source",
                    "intended_pedestrian_use_source", "sidewalk_polygon_m")
    if any(not map_packet.get(k) for k in required_map):
        raise ValueError("sidewalk map and context source provenance required")
    if len(trace) != FRAME_COUNT:
        raise ValueError("trace must contain 600 frames")
    stopped = overlap = stopped_overlap = whole = 0
    first_stop = last_stop = None
    for i, row in enumerate(trace):
        if row.get("frame") != i or abs(row.get("time_s", -1) - i / FRAME_RATE) > 1e-6:
            raise ValueError("20 Hz source frame join failed")
        if not row.get("actor_pose_source") or not row.get("velocity_source"):
            raise ValueError("raw actor pose and velocity source required")
        try:
            speed = float(row["speed_mps"])
        except (ValueError, TypeError, KeyError) as exc:
            raise ValueError("raw speed required") from exc
        if not isfinite(speed) or speed < 0:
            raise ValueError("raw speed invalid")
        m = measure_frame(row.get("vehicle_footprint_m"), map_packet["sidewalk_polygon_m"])
        # 0.05 m/s is an engineering stop-state threshold, not statutory meaning.
        at_rest = speed <= 0.05
        stopped += at_rest
        overlap += m["overlap_positive"]
        stopped_overlap += at_rest and m["overlap_positive"]
        whole += at_rest and m["entire_vehicle_on_sidewalk"]
        if at_rest:
            first_stop = i if first_stop is None else first_stop
            last_stop = i
    return {
        "frames": FRAME_COUNT, "frame_rate_hz": FRAME_RATE,
        "first_rest_frame": first_stop, "last_rest_frame": last_stop,
        "rest_frames": stopped, "overlap_frames": overlap,
        "rest_and_overlap_frames": stopped_overlap,
        "entire_footprint_rest_frames": whole,
        "map_sha256": map_sha256, "trace_sha256": trace_sha256,
        "exception_sources": {
            "traffic_conflict": None, "other_law": None,
            "officer_direction": None, "official_device": None,
            "subsection_3_actor": None,
        },
        "sidewalk_legal_status": None,
        "legal_conclusion": None,
    }
